{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Camellianin B, a flavonoid diglycoside, was detected in rat brain after intragastric administration of camellianin A, directly demonstrating that a highly polar flavonoid glycoside can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Cyanidin-3-O-glucoside was detected in rat brain after intravenous administration and in human brain vascular endothelium, providing direct evidence that a charged anthocyanin glucoside reaches brain tissue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, showing meaningful brain exposure despite glycoside polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Rutin and hyperoside, flavonol glycosides, were detected in rat brain after oral administration, supporting brain access for glycosylated flavonoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "EH-201, a glycoside, was detected in rabbit CSF after gavage, providing direct CSF evidence of BBB passage for a polar glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ciwujianoside B, a glycoside, was detected in mouse cerebral cortex after oral administration, confirming brain penetration of a polar glycoside.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Despite unfavorable passive-diffusion physicochemical properties, multiple high-transfer direct in vivo studies show that flavonoid/anthocyanin glycosides and related polar glycosides cross the BBB and reach brain/CSF. The query is a flavonoid C-glucoside in the same chemical class, so meaningful CNS access is supported.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma ratio or unbound brain concentration is available for the exact query molecule.",
    "C-glucoside versus O-glucoside/anthocyanin differences in transporter handling are not fully resolved.",
    "Human data for the query class are limited, and efflux liability is not quantitatively defined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

